// ¿HUBO UN CIERRE DE VENTA?
//
// La prueba NO es que el modelo diga que el pedido está confirmado. Eso ya nos
// costó caro en el Demo A: el marcador lo escribe el modelo, así que es una
// afirmación, no un hecho. La prueba de que el cliente pagó es que el CLIENTE
// MANDÓ UNA IMAGEN — el comprobante — y que sobre ese mensaje el asistente
// respondió dando el pago por recibido.
//
// Las dos condiciones juntas dejan afuera exactamente lo que la oferta excluye:
// mandar el QR y que el cliente no pague (no hay imagen), y mandar información
// que nadie confirma (no hay imagen ni confirmación).
//
// La referencia es el id del mensaje de WhatsApp de esa imagen: existe fuera de
// nosotros, es único, y permite ir a buscar el comprobante si alguien discute
// la factura.
const item = $json;
const esImagenDelCliente = item.tipo === 'image';
const confirmoElPago = /SIMULADO/i.test(String(item.texto ?? ''));
const referencia = String(item.mensajeId ?? '');

return [{ json: {
  ...item,
  hayCierre: Boolean(esImagenDelCliente && confirmoElPago && referencia),
  referenciaCierre: referencia,
} }];
